1926	                                next with { Ai = next.Ai with { Onboarded = true } });
1927	                            onboardingCompleted = true;
1928	                            return true;
1929	                        }
1930	                        catch (JsonStoreException ex)
1931	                        {
1932	                            PersistenceErrorPresenter.Report(ex, this);
1933	                            return false;
1934	                        }
1935	                    });
1936	                welcome.Owner = this;
1937	                welcome.ShowDialog();
1938	            }
1939	        }
1940	        if (onboardingRequired && !onboardingCompleted)
1941	            return;
1942	        if (onboardingCompleted)
1943	            next = next with { Ai = next.Ai with { Onboarded = true } };
1944	
1945	        try
1946	        {
1947	            _store.SaveSettings(next);
1948	        }
