1950	        {
1951	            PersistenceErrorPresenter.Report(ex, this);
1952	            _manager.RefreshSettingsWindow();
1953	            return;
1954	        }
1955	
1956	        _settings = next;
1957	        _manager.ApplySettings(next);
1958	        _ai?.ApplySettings(next); // AI 设置同步（总开关启停 Agent / 配置下发）
1959	    }
