  1	using DesktopPet.Infra.Hotkey;
  2	
  3	namespace DesktopPet.Infra.Tests;
  4	
  5	/// <summary>
  6	/// Phase 6h：全局快捷键（bongo-cat-next 借鉴；迁移计划 §5 Phase 6）。
  7	/// Ctrl+Alt+H 显隐 / Ctrl+Alt+M 切换模式 / Ctrl+Alt+S 设置 / Ctrl+Alt+Q 退出。
  8	/// RegisterHotKey P/Invoke；WndProc 接线在 App 层（WM_HOTKEY 分发）。
  9	/// </summary>
 10	public class HotkeyManagerTests
 11	{
 12	    private sealed class FakeHotkeyRegistration : IHotkeyRegistration
 13	    {
 14	        public List<(int Id, uint Mods, uint Key)> Registered { get; } = [];
 15	        public List<int> Unregistered { get; } = [];
 16	        public bool FailNext { get; set; }
 17	
 18	        public bool Register(IntPtr hwnd, int id, uint modifiers, uint virtualKey)
 19	        {
 20	            if (FailNext) { FailNext = false; return false; }
 21	            Registered.Add((id, modifiers, virtualKey));
 22	            return true;
 23	        }
 24	
 25	        public bool Unregister(IntPtr hwnd, int id)
 26	        {
 27	            Unregistered.Add(id);
 28	            return true;
 29	        }
 30	    }
 31	
 32	    private static readonly (HotkeyAction Action, uint Mods, uint Key)[] Presets =
 33	    [
 34	        (HotkeyAction.TogglePets, HotkeyManager.ModControlAlt, 'H'),
 35	        (HotkeyAction.ToggleMode, HotkeyManager.ModControlAlt, 'M'),
 36	        (HotkeyAction.OpenSettings, HotkeyManager.ModControlAlt, 'S'),
 37	        (HotkeyAction.Quit, HotkeyManager.ModControlAlt, 'Q'),
 38	    ];
 39	
 40	    [Fact]
 41	    public void Register_AssignsIds_AndResolvesActions()
 42	    {
 43	        var fake = new FakeHotkeyRegistration();
 44	        var manager = new HotkeyManager(IntPtr.Zero, fake);
 45	
 46	        foreach (var (action, mods, key) in Presets)
 47	            Assert.True(manager.Register(action, mods, key));
 48	
 49	        Assert.Equal(4, fake.Registered.Count);
 50	        // 每个注册 id 都映射回对应 action
 51	        foreach (var (id, _, _) in fake.Registered)
 52	            Assert.NotNull(manager.Resolve(id));
 53	        Assert.Equal(HotkeyAction.Quit, manager.Resolve(fake.Registered[3].Id));
 54	        Assert.Equal(HotkeyAction.TogglePets, manager.Resolve(fake.Registered[0].Id));
 55	    }
 56	
 57	    [Fact]
 58	    public void Register_ReRegisterSameAction_UnregistersOldId()
 59	    {
 60	        var fake = new FakeHotkeyRegistration();
 61	        var manager = new HotkeyManager(IntPtr.Zero, fake);
 62	
 63	        Assert.True(manager.Register(HotkeyAction.TogglePets, HotkeyManager.ModControlAlt, 'H'));
 64	        var firstId = fake.Registered[0].Id;
 65	        Assert.True(manager.Register(HotkeyAction.TogglePets, HotkeyManager.ModControlAlt, 'H'));
 66	
 67	        Assert.Contains(firstId, fake.Unregistered);          // 旧 id 已注销
 68	        Assert.Equal(2, fake.Registered.Count);
 69	        Assert.Equal(HotkeyAction.TogglePets, manager.Resolve(fake.Registered[1].Id));
 70	    }
 71	
 72	    [Fact]
 73	    public void Register_Failure_LeavesNoMapping()
 74	    {
 75	        var fake = new FakeHotkeyRegistration { FailNext = true };
 76	        var manager = new HotkeyManager(IntPtr.Zero, fake);
 77	
 78	        Assert.False(manager.Register(HotkeyAction.Quit, HotkeyManager.ModControlAlt, 'Q'));
 79	        Assert.Empty(fake.Registered);
 80	        Assert.Null(manager.Resolve(0xC000));
 81	    }
 82	
 83	    [Fact]
 84	    public void UnregisterAll_ClearsMappings()
 85	    {
 86	        var fake = new FakeHotkeyRegistration();
 87	        var manager = new HotkeyManager(IntPtr.Zero, fake);
 88	        manager.Register(HotkeyAction.Quit, HotkeyManager.ModControlAlt, 'Q');
 89	
 90	        manager.UnregisterAll();
 91	
 92	        Assert.Single(fake.Unregistered);
 93	        Assert.Null(manager.Resolve(fake.Registered[0].Id));
 94	    }
 95	
 96	    [Fact]
 97	    public void Resolve_UnknownId_ReturnsNull()
 98	    {
 99	        var manager = new HotkeyManager(IntPtr.Zero, new FakeHotkeyRegistration());
100	        Assert.Null(manager.Resolve(0x1234));
101	    }
102	
103	    [Fact]
104	    public void Presets_UseExpectedModifiersAndKeys()
105	    {
106	        Assert.All(Presets, p =>
107	        {
108	            Assert.Equal(HotkeyManager.ModControlAlt, p.Mods);
109	            Assert.InRange(p.Key, 'A', 'Z');
110	        });
111	        Assert.Equal('H', Presets[0].Key);
112	        Assert.Equal('M', Presets[1].Key);
113	        Assert.Equal('S', Presets[2].Key);
114	        Assert.Equal('Q', Presets[3].Key);
115	    }
116	}
