  8	public class AppSettingsTests
  9	{
 10	    [Fact]
 11	    public void Defaults_UseDetectedLanguage()
 12	    {
 13	        var defaults = AppSettings.Defaults(AppLang.ZhHans);
 14	
 15	        Assert.Equal("system", defaults.Theme);
 16	        Assert.Equal(92, defaults.BubbleOpacity);
 17	        Assert.Equal(4, defaults.QuickBubbleDurationSeconds);
 18	        Assert.Equal(AppLang.ZhHans, defaults.Lang);
 19	        Assert.Equal(RoamMode.Wander, defaults.Roam.Mode);
 20	    }
 21	
 22	    [Fact]
 23	    public void Normalize_ClampsAndFallsBack()
 24	    {
 25	        var raw = new AppSettings(
 26	            Theme: "neon", BubbleOpacity: 500, FontSize: 0, FontFamily: "comic",
 27	            ShowIdleChatter: false, IdleChatterIntervalSeconds: 999, AnimationEnabled: false,
 28	            BobAnimation: true, PetSizePercent: 999,
 29	            LeftClickAction: "all", QuickBubbleDurationSeconds: 99,
 30	            QuickBubblePresets: ["x"], IdleChatterLines: [], HungryLines: [],
 31	            Roam: new RoamConfig(true, (RoamMode)42, 0, 100, 99_999),
 32	            Lang: AppLang.En,
 33	            Ai: AiSettings.Defaults);
 34	
 35	        var n = AppSettings.Normalize(raw);
 36	
 37	        Assert.Equal("system", n.Theme);
 38	        Assert.Equal(100, n.BubbleOpacity);
 39	        Assert.Equal(8, n.FontSize);
 40	        Assert.Equal("system", n.FontFamily);
 41	        Assert.Equal(130, n.PetSizePercent);
 42	        Assert.Equal(120, n.IdleChatterIntervalSeconds); // 上限钳制
 43	        Assert.False(n.AnimationEnabled);
 44	        Assert.Equal("all", n.LeftClickAction);
 45	        Assert.Equal(10, n.QuickBubbleDurationSeconds);
 46	        Assert.Empty(n.IdleChatterLines); // 用户显式清空 [] → 保留（不显示闲谈）
 47	        Assert.Empty(n.HungryLines);
 48	        Assert.Equal(RoamMode.Wander, n.Roam.Mode); // 非法 mode 回退
 49	        Assert.Equal(1, n.Roam.Speed);              // 速度下限
 50	        Assert.Equal(1200, n.Roam.WanderPauseMinMs); // 低于下限回退默认
 51	    }
 52	
 53	    [Fact]
 54	    public void Normalize_MissingChatterLines_FallBackToDefaults()
 55	    {
 56	        // 旧 JSON 无台词池字段（null）→ 默认台词；显式空数组 → 保留空（用户关闭闲谈内容）
 57	        var raw = AppSettings.Defaults(AppLang.En) with
 58	        {
 59	            IdleChatterLines = null!,
 60	            HungryLines = null!,
 61	        };
 62	
 63	        var n = AppSettings.Normalize(raw);
 64	
 65	        Assert.Equal(AppSettings.DefaultIdleChatterLines, n.IdleChatterLines);
 66	        Assert.Equal(AppSettings.DefaultHungryLines, n.HungryLines);
 67	    }
 68	
 69	    [Fact]
 70	    public void Defaults_HaveChatterAndHungryLines()
 71	    {
 72	        var defaults = AppSettings.Defaults(AppLang.ZhHans);
 73	
 74	        Assert.Equal(6, defaults.IdleChatterLines.Length);
 75	        Assert.Equal(4, defaults.HungryLines.Length);
 76	    }
 77	
 78	    [Fact]
 79	    public void Normalize_KeepsValidValues()
 80	    {
 81	        var raw = AppSettings.Defaults(AppLang.En) with
 82	        {
 83	            Theme = "dark",
 84	            BubbleOpacity = 70,
 85	            FontSize = 13,
 86	            FontFamily = "rounded",
 87	            LeftClickAction = "self",
 88	            QuickBubbleDurationSeconds = 6,
 89	        };
 90	
 91	        var n = AppSettings.Normalize(raw);
 92	
 93	        Assert.Equal("dark", n.Theme);
 94	        Assert.Equal(70, n.BubbleOpacity);
 95	        Assert.Equal(13, n.FontSize);
 96	        Assert.Equal("rounded", n.FontFamily);
 97	        Assert.Equal("self", n.LeftClickAction);
 98	        Assert.Equal(6, n.QuickBubbleDurationSeconds);
 99	    }
100	
101	    [Fact]
102	    public void Normalize_ClampsIdleChatterIntervalFloor()
103	    {
104	        var raw = AppSettings.Defaults(AppLang.En) with { IdleChatterIntervalSeconds = 1 };
105	        Assert.Equal(5, AppSettings.Normalize(raw).IdleChatterIntervalSeconds);
106	    }
107	}

